-- ----------------------------
DROP TABLE IF EXISTS `ta_banner`;
CREATE TABLE `ta_banner` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `refid` bigint(20) DEFAULT NULL COMMENT '关联id',
  `title` varchar(255) COLLATE utf8_bin DEFAULT NULL COMMENT '标题',
  `subtitle` varchar(255) COLLATE utf8_bin DEFAULT NULL COMMENT '副标题',
  `cover_url` varchar(255) COLLATE utf8_bin DEFAULT NULL COMMENT '封面',
  `state` int(11) DEFAULT NULL COMMENT '状态： 0正常 1禁用',
  `seq` int(11) DEFAULT NULL COMMENT '序号',
  `type` int(11) DEFAULT NULL COMMENT '类型：1游记 2:攻略',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8 COLLATE=utf8_bin ROW_FORMAT=DYNAMIC COMMENT='文章推荐表';

