-- ----------------------------
-- Table structure for ta_destination
-- ----------------------------
DROP TABLE IF EXISTS `ta_destination`;
CREATE TABLE `ta_destination` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(255) DEFAULT NULL COMMENT '中文名称',
  `english` varchar(255) DEFAULT NULL COMMENT '英文名称',
  `cover_url` varchar(255) DEFAULT NULL COMMENT '封面图片',
  `info` varchar(255) DEFAULT NULL COMMENT '介绍',
  `parent_name` varchar(255) DEFAULT NULL COMMENT '上级名称',
  `parent_id` bigint(20) DEFAULT NULL COMMENT '上级ID',
  `region_id` int(11) DEFAULT NULL COMMENT '地区(板块)归属',
  `status` int(11) NOT NULL DEFAULT '0' COMMENT '0正常 1审核中',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=609 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='目的地表';

