-- ----------------------------
-- Table structure for ta_note
-- ----------------------------
DROP TABLE IF EXISTS `ta_note`;
CREATE TABLE `ta_note` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dest_id` bigint(20) DEFAULT NULL COMMENT '目的地id',
  `dest_name` varchar(255) DEFAULT NULL COMMENT '目的地',
  `author_id` bigint(20) DEFAULT NULL COMMENT '作者id',
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `summary` varchar(255) DEFAULT NULL COMMENT '概要',
  `cover_url` varchar(255) DEFAULT NULL COMMENT '封面',
  `travel_time` datetime DEFAULT NULL COMMENT '旅游时间',
  `avg_consume` int(11) DEFAULT NULL COMMENT '人均消费',
  `days` int(11) DEFAULT NULL COMMENT '旅游天数',
  `person` varchar(20) DEFAULT NULL COMMENT '和谁旅游',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `release_time` datetime DEFAULT NULL COMMENT '发布时间',
  `update_time` datetime DEFAULT NULL COMMENT '最新更新时间内',
  `is_public` varchar(20) CHARACTER SET utf8mb4 DEFAULT '0' COMMENT '是否公开 0:否 1:是',
  `viewnum` int(11) DEFAULT '0' COMMENT '点击/阅读数',
  `replynum` int(11) DEFAULT '0' COMMENT '回复数',
  `favornum` int(11) DEFAULT '0' COMMENT '收藏数',
  `sharenum` int(11) DEFAULT '0' COMMENT '分享数',
  `thumbsupnum` int(11) DEFAULT '0' COMMENT '点赞数',
  `status` varchar(20) DEFAULT NULL COMMENT '游记状态 0:草稿 1:待发布(待审核) 2:审核通过 3:拒绝',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='旅游日记表';

-- ----------------------------
-- Records of ta_note
-- ----------------------------

-- ----------------------------
-- Table structure for ta_note_comment
-- ----------------------------
DROP TABLE IF EXISTS `ta_note_comment`;
CREATE TABLE `ta_note_comment` (
