  `note_id` bigint(20) DEFAULT NULL COMMENT '游记id',
  `note_title` varchar(255) DEFAULT NULL COMMENT '游记标题',
  `user_id` bigint(20) DEFAULT NULL COMMENT '用户id',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `content` text CHARACTER SET utf8mb4 COMMENT '评论内容',
  `type` varchar(20) DEFAULT NULL COMMENT '评论类型',
  `status` varchar(20) DEFAULT '0' COMMENT '评论状态',
  `ref_id` bigint(20) DEFAULT NULL COMMENT '关联id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='游记评论表';

