  `sn` varchar(255) DEFAULT NULL COMMENT '编码',
  `ishot` int(11) DEFAULT NULL COMMENT '是否热门，0非热门，1:热门',
  `seq` int(11) DEFAULT NULL COMMENT '展示顺序',
  `info` varchar(255) DEFAULT NULL COMMENT '介绍',
  `ref_ids` text COMMENT '关联id集合',
  PRIMARY KEY (`id`) USING BTREE
