-- ----------------------------
-- Table structure for ta_strategy
-- ----------------------------
DROP TABLE IF EXISTS `ta_strategy`;
CREATE TABLE `ta_strategy` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dest_id` bigint(20) DEFAULT NULL COMMENT '引用目的地ID',
  `dest_name` varchar(255) DEFAULT NULL COMMENT '引用目的地名称',
  `theme_id` bigint(20) DEFAULT NULL COMMENT '引用主题ID',
  `theme_name` varchar(255) DEFAULT NULL COMMENT '引用主题名称',
  `catalog_id` bigint(20) DEFAULT NULL COMMENT '引用分类ID',
  `catalog_name` varchar(255) DEFAULT NULL COMMENT '引用分类名称',
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `sub_title` varchar(255) DEFAULT NULL COMMENT '副标题',
  `summary` varchar(255) DEFAULT NULL COMMENT '内容概要',
  `cover_url` varchar(255) DEFAULT NULL COMMENT '封面图片地址',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `isabroad` int(11) DEFAULT NULL COMMENT '是否为国外，0表示国内，1表示国外',
  `viewnum` int(11) DEFAULT NULL COMMENT '点击数',
  `replynum` int(11) DEFAULT NULL COMMENT '攻略评论数',
  `favornum` int(11) DEFAULT NULL COMMENT '收藏数',
  `sharenum` int(11) DEFAULT NULL COMMENT '分享数',
  `thumbsupnum` int(11) DEFAULT NULL COMMENT '点赞数',
  `state` int(11) DEFAULT NULL COMMENT '状态，0表示待发布，1表示发布',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='攻略表';

