  `dest_name` varchar(255) DEFAULT NULL COMMENT '目的名称',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='攻略分类表';

