-- ----------------------------
-- Table structure for ta_strategy_theme
-- ----------------------------
DROP TABLE IF EXISTS `ta_strategy_theme`;
CREATE TABLE `ta_strategy_theme` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(255) DEFAULT NULL COMMENT '主题名称',
  `state` int(11) DEFAULT NULL COMMENT '主题状态',
  `seq` int(11) DEFAULT NULL COMMENT '序号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='攻略主题';

